class BackendServiceClientSync(ConnectClientSync):
    """
    BackendService manages physical storage backends. Exclusive to platform
    admins; bucket admins use ListBackends (read-only) to pick a target.
    """
    def __init__(
        self,
        address: str,
        *,
        codec: Codec | None = _PROTO_BINARY_CODEC,
        protocol: ProtocolType = ProtocolType.CONNECT,
        accept_compression: Iterable[Compression] | None = None,
        send_compression: Compression | None = _GZIP_COMPRESSION,
        timeout_ms: int | None = None,
        read_max_bytes: int | None = None,
        interceptors: Iterable[InterceptorSync] = (),
        http_client: SyncClient | None = None,
    ) -> None:
        super().__init__(
            address=address,
            codec=codec,
            protocol=protocol,
            accept_compression=accept_compression,
            send_compression=send_compression,
            timeout_ms=timeout_ms,
            read_max_bytes=read_max_bytes,
            interceptors=interceptors,
            http_client=http_client,
        )
    def create_backend(
        self,
        request: CreateBackendRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> StorageBackend:
        """
        CreateBackend registers an S3-compatible endpoint. Credentials are stored
        via SecretRef, never inline in the resource.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="CreateBackend",
                service_name="paladin.admin.v1.BackendService",
                input=CreateBackendRequest,
                output=StorageBackend,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def get_backend(
        self,
        request: GetBackendRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
        use_get: bool = False,
    ) -> StorageBackend:
        """
        GetBackend returns the backend by id. Credentials are never echoed back.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="GetBackend",
                service_name="paladin.admin.v1.BackendService",
                input=GetBackendRequest,
                output=StorageBackend,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
            use_get=use_get,
        )
    def update_backend(
        self,
        request: UpdateBackendRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> StorageBackend:
        """
        UpdateBackend applies update_mask; resource_version is required. Changing
        the endpoint of a backend with live buckets does not migrate anything —
        the objects stay where they are.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="UpdateBackend",
                service_name="paladin.admin.v1.BackendService",
                input=UpdateBackendRequest,
                output=StorageBackend,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def delete_backend(
        self,
        request: DeleteBackendRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> DeleteBackendResponse:
        """
        DeleteBackend refuses while buckets still reference it. No flag overrides
        that — buckets.backend_id is ON DELETE RESTRICT, so the refusal comes from
        the database. resource_version is required.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="DeleteBackend",
                service_name="paladin.admin.v1.BackendService",
                input=DeleteBackendRequest,
                output=DeleteBackendResponse,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def list_backends(
        self,
        request: ListBackendsRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
        use_get: bool = False,
    ) -> ListBackendsResponse:
        """
        ListBackends returns every registered backend for the platform; backends
        are not tenant-scoped.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="ListBackends",
                service_name="paladin.admin.v1.BackendService",
                input=ListBackendsRequest,
                output=ListBackendsResponse,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
            use_get=use_get,
        )
    def rotate_credentials(
        self,
        request: RotateCredentialsRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> StorageBackend:
        """
        RotateCredentials swaps the credentials_secret_ref. The previous secret
        remains valid for `grace_period` so in-flight presigns don't break.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="RotateCredentials",
                service_name="paladin.admin.v1.BackendService",
                input=RotateCredentialsRequest,
                output=StorageBackend,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def test_backend(
        self,
        request: TestBackendRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> TestBackendResponse:
        """
        TestBackend performs a connectivity probe (HEAD / list-buckets). Read-only.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="TestBackend",
                service_name="paladin.admin.v1.BackendService",
                input=TestBackendRequest,
                output=TestBackendResponse,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def set_backend_enabled(
        self,
        request: SetBackendEnabledRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> StorageBackend:
        """
        SetBackendEnabled flips the backend's enabled state. Idempotent
        (setting the current state is a no-op success). OCC-guarded via
        resource_version. Disabling the configured default backend is
        refused (FailedPrecondition).
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="SetBackendEnabled",
                service_name="paladin.admin.v1.BackendService",
                input=SetBackendEnabledRequest,
                output=StorageBackend,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def set_backend_read_only(
        self,
        request: SetBackendReadOnlyRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> StorageBackend:
        """
        SetBackendReadOnly flips the backend's read-only "drain" state
        (`001_initial_schema.sql`). Idempotent, OCC-guarded via resource_version. Only
        meaningful on an enabled backend: reads keep working, mutations are
        refused so an operator can migrate data off before disabling.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="SetBackendReadOnly",
                service_name="paladin.admin.v1.BackendService",
                input=SetBackendReadOnlyRequest,
                output=StorageBackend,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def set_backend_maintenance(
        self,
        request: SetBackendMaintenanceRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> StorageBackend:
        """
        SetBackendMaintenance raises/clears the operator-set, advisory
        maintenance flag (`001_initial_schema.sql`). Idempotent, OCC-guarded via
        resource_version. Advisory — it does not gate operations.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="SetBackendMaintenance",
                service_name="paladin.admin.v1.BackendService",
                input=SetBackendMaintenanceRequest,
                output=StorageBackend,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
